<?php

use App\Http\Controllers\AuthController;
use App\Http\Controllers\FinanceController;
use App\Http\Controllers\PayrollController;
use App\Http\Controllers\ReportController;
use App\Http\Controllers\TranscriptController;
use Illuminate\Support\Facades\Route;

/*
|--------------------------------------------------------------------------
| مسیرهای سامانه
|--------------------------------------------------------------------------
| هر مسیر حساس با `role:` محافظت می‌شود. پنهان کردن لینک از منو امنیت نیست؛
| مجوز باید در لایه route اعمال شود، وگرنه هر کسی که آدرس را بداند دورش
| می‌زند.
*/

Route::redirect('/', '/dashboard');

// ── عمومی ────────────────────────────────────────────────────
Route::middleware('guest')->group(function () {
    Route::get('/login', [AuthController::class, 'showLogin'])->name('login');
    Route::post('/login', [AuthController::class, 'login'])->name('login.store');
});

Route::post('/logout', [AuthController::class, 'logout'])
    ->middleware('auth')->name('logout');

// ── نیازمند ورود ─────────────────────────────────────────────
Route::middleware('auth')->group(function () {

    Route::livewire('/dashboard', 'pages::dashboard.index')->name('dashboard');

    // دانش‌آموزان: مدیر، معاون، پذیرش، و امور مالی که فقط وضعیت بدهی را می‌بیند
    Route::livewire('/students', 'pages::students.index')
        ->middleware('role:admin,deputy,finance,reception')
        ->name('students.index');

    // پروندهٔ یک دانش‌آموز. نقش‌ها مثل فهرست‌اند و خود صفحه بخش‌هایی را که
    // آن نقش اجازه ندارد (نمره برای امور مالی) پنهان می‌کند.
    Route::livewire('/students/{student}', 'pages::students.show')
        ->middleware('role:admin,deputy,finance,reception')
        ->name('students.show');

    // کارنامهٔ رسمی چاپی؛ بدون layout پنل، مثل چاپ فاکتور و فیش حقوقی.
    // نقش‌ها همان نقش‌های بخش نمرات‌اند (Role::sections): امور مالی و پذیرش
    // نمره نمی‌بینند، پس کارنامه هم نمی‌گیرند.
    Route::get('/students/{student}/transcript', [TranscriptController::class, 'print'])
        ->middleware('role:admin,deputy,teacher')
        ->name('students.transcript.print');

    // دوره‌ها: مدیر، معاون (ثبت‌نام و ارزیابی)، پذیرش (ثبت‌نام و فاکتور) و
    // دبیر برای «کلاس‌های خودش». امور مالی دوره را می‌بیند ولی ویرایشش نه.
    Route::livewire('/courses', 'pages::courses.index')
        ->middleware('role:admin,deputy,reception,teacher')
        ->name('courses.index');

    // کارنامهٔ نهایی دوره: همان نقش‌های بخش نمرات. امور مالی و پذیرش دوره را
    // می‌بینند ولی نمرهٔ دانش‌آموزان کار آن‌ها نیست، پس سندی که همهٔ نمرات
    // یک کلاس را چاپ می‌کند را هم نمی‌گیرند.
    Route::get('/courses/{course}/transcript', [TranscriptController::class, 'printCourse'])
        ->middleware('role:admin,deputy,teacher')
        ->name('courses.transcript.print');

    // حضور و غیاب روزانه: همان نقش‌هایی که بخش «حضور و غیاب» را می‌بینند
    // (Role::sections). پذیرش این‌جا نیست چون ثبت‌نام کار اوست نه حضور کلاس،
    // و امور مالی چون نمره و حضور کارش نیست.
    Route::livewire('/attendance', 'pages::attendance.index')
        ->middleware('role:admin,deputy,teacher')
        ->name('attendance.index');

    // تقویم شمسی کلاس‌ها و تعارض‌ها: همان نقش‌های بخش زمان‌بندی. دبیر فقط
    // کلاس‌های خودش را می‌بیند؛ پذیرش و امور مالی کاری به برنامهٔ کلاس ندارند
    Route::livewire('/schedule', 'pages::schedule.index')
        ->middleware('role:admin,deputy,teacher')
        ->name('schedule.index');

    // اساتید و حقوق: فقط مدیر و معاون. امور مالی دسترسی ندارد چون حقوق
    // همان‌جاست و دبیر نباید لیست حقوق را ببیند.", "exit_code": 0, "error": null}

