{"content":"<?php

namespace Tests\Feature;

use App\Services\ExportService;
use Illuminate\Testing\TestResponse;
use Tests\Concerns\ReadsXlsx;
use Tests\TestCase;

/*
|---------------------------------------------------------------------------
| خروجی اکسل گزارش‌ها (شماره 60)
|
| فایل باید واقعی .xlsx باشد: zip با ساختار OOXML. CSV با BOM در اکسل
| فارسی باز می‌شود ولی ستون‌ها را متن می‌بیند و جمع نمی‌زند؛ سربرگ هم
| باید فارسی باشد وگرنه فایل به‌درد گزارش فارسی نمی‌خورد.
*/

class ExportServiceTest extends TestCase
{
    use ReadsXlsx;

    private function export(): TestResponse
    {
        $response = (new ExportService)->excel('balances', [
            'student' => 'دانش‌آموز',
            'outstanding' => 'مانده',
        ], [
            ['student' => 'زهرا کریمی', 'outstanding' => 2_000_000],
        ]);

        return TestResponse::fromBaseResponse($response);
    }

    public function test_the_file_is_a_readable_xlsx_with_persian_column_names(): void
    {
        $sheet = $this->sheetXml($this->export()->streamedContent());

        $this->assertStringContainsString('دانش‌آموز', $sheet);
        $this->assertStringContainsString('مانده', $sheet);
        $this->assertStringContainsString('زهرا کریمی', $sheet);
    }

    public function test_the_download_is_offered_as_an_excel_file(): void
    {
        $response = $this->export();

        $response->assertDownload();

        $disposition = (string) $response->headers->get('content-disposition');

        // نام فایل لاتین می‌ماند: نامِ فارسی در هدر پاسخ بسته به مرورگر
        // می‌شکند و فایل دانلودشده بی‌نام می‌شود.
        $this->assertStringContainsString('balances-', $disposition);
        $this->assertStringContainsString('.xlsx', $disposition);
        $this->assertStringContainsString(
            'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            (string) $response->headers->get('content-type'),
        );
    }

    public function test_the_sheet_reads_right_to_left(): void
    {
        $sheet = $this->sheetXml($this->export()->streamedContent());

        // جدولِ راست‌به‌چپ تنها چیزی است که اکسل را برای متن فارسی درست می‌کند؛
        // بدون آن ستون اول در سمت چپ می‌نشیند و ردیف‌ها برعکس خوانده می‌شوند.
        $this->assertStringContainsString('rightToLeft="1"', $sheet);
    }

    public function test_money_is_written_as_a_number_so_it_can_be_summed(): void
    {
        $sheet = $this->sheetXml($this->export()->streamedContent());

        $this->assertStringContainsString('<v>2000000</v>', $sheet);
        $this->assertStringNotContainsString('t="inlineStr"><is><t>2000000', $sheet);
    }

    public function test_persian_text_and_digits_survive_in_a_text_cell(): void
    {
        $response = TestResponse::fromBaseResponse(
            (new ExportService)->excel('balances', ['date' => 'آخرین پرداخت'], [
                ['date' => to_persian_digits('1405/08/12')],
            ]),
        );

        $sheet = $this->sheetXml($response->streamedContent());

        $this->assertStringContainsString('۱۴۰۵/۰۸/۱۲', $sheet);
    }

    public function test_an_empty_report_still_produces_a_file_with_its_headers(): void
    {
        $response = TestResponse::fromBaseResponse(
            (new ExportService)->excel('balances', ['student' => 'دانش‌آموز'], []),
        );

        $response->assertDownload();

        $sheet = $this->sheetXml($response->streamedContent());

        // گزارش خالی هم سند است: ستون‌ها باید باشند تا بتوان روی همان فایل
        // پر کرد یا ثابت کرد که گزارش واقعاً هیچ ردیفی نداشته است.
        $this->assertStringContainsString('دانش‌آموز', $sheet);
        $this->assertStringNotContainsString('<row r="2"', $sheet);
    }
}
