namespace Tests\Feature;

use App\Enums\Role;
use App\Models\Discipline;
use App\Models\Student;
use App\Models\User;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Livewire\Livewire;
use Tests\Concerns\ReadsXlsx;
use Tests\TestCase;

/*
|---------------------------------------------------------------------------
| خروجی اکسل همهٔ گزارش‌ها (شماره 60)
|
| یک سرویس مشترک برای هر پنج گزارش: سه تا کنترلری (وصولی، آموزشی، سود و
| زیان) و دو تا Livewire (ساعت کارکرد، انضباط). اینجا ثابت می‌شود که هر
| پنج تا فایل واقعی می‌دهند و نام ستون‌هایشان فارسی است.
*/

class ReportExportTest extends TestCase
{
    use RefreshDatabase;
    use ReadsXlsx;

    // ── گزارش‌های کنترلری ─────────────────────────────────────

    public function test_the_balance_report_downloads_an_excel_file_with_persian_columns(): void
    {
        $this->actingAs(User::factory()->role(Role::Finance)->create());
        Student::factory()->create(['first_name' => 'زهرا', 'last_name' => 'کریمی']);

        $response = $this->get(route('reports.balances', ['format' => 'excel']));

        $response->assertOk()->assertDownload();

        $sheet = $this->sheetXml($response->streamedContent());

        $this->assertStringContainsString('دانش‌آموز', $sheet);
        $this->assertStringContainsString('جمع فاکتور', $sheet);
        $this->assertStringContainsString('مانده', $sheet);
        $this->assertStringContainsString('زهرا', $sheet);
    }

    public function test_the_academic_report_downloads_an_excel_file_with_persian_columns(): void
    {
        $this->actingAs(User::factory()->role(Role::Admin)->create());
        Student::factory()->create(['first_name' => 'امیر']);

        $response = $this->get(route('reports.academic', ['format' => 'excel']));

        $response->assertOk()->assertDownload();

        $sheet = $this->sheetXml($response->streamedContent());

        $this->assertStringContainsString('درصد حضور', $sheet);
        $this->assertStringContainsString('میانگین نمرات', $sheet);
        $this->assertStringContainsString('امیر', $sheet);
    }

    public function test_the_profit_and_loss_report_downloads_an_excel_file_with_persian_columns(): void
    {
        $this->actingAs(User::factory()->role(Role::Finance)->create());

        $response = $this->get(route('reports.profit-and-loss', ['format' => 'excel']));

        $response->assertOk()->assertDownload();

        $sheet = $this->sheetXml($response->streamedContent());

        $this->assertStringContainsString('مبلغ (تومان)', $sheet);
        $this->assertStringContainsString('درآمد (وصولی)', $sheet);
    }

    public function test_an_unknown_format_still_renders_the_report_page(): void
    {
        $this->actingAs(User::factory()->role(Role::Finance)->create());

        // پارامترِ ناشناخته نباید گزارش را بکشد؛ فقط «excel» معنای خروجی دارد
        $this->get(route('reports.balances', ['format' => 'pdf']))
            ->assertOk()
            ->assertSee('گزارش وصولی و بدهکاران');
    }

    public function test_the_report_pages_offer_the_excel_export(): void
    {
        $this->actingAs(User::factory()->role(Role::Finance)->create());

        $this->get(route('reports.balances'))
            ->assertOk()
            ->assertSee('format=excel', false);
    }

    // ── گزارش‌های Livewire ────────────────────────────────────

    public function test_the_teacher_hours_report_downloads_an_excel_file_with_persian_columns(): void
    {
        $this->actingAs(User::factory()->role(Role::Admin)->create());

        $download = $this->downloadFrom('pages::reports.teacher-hours');

        $this->assertStringContainsString('.xlsx', $download['name']);

        $sheet = $this->sheetXml(base64_decode($download['content']));

        $this->assertStringContainsString('جلسات برگزارشده', $sheet);
        $this->assertStringContainsString('ساعت', $sheet);
    }

    public function test_the_discipline_report_downloads_an_excel_file_with_persian_columns(): void
    {
        $this->actingAs(User::factory()->role(Role::Admin)->create());
        Discipline::factory()->create(['description' => 'با تأخیر وارد کلاس شد']);

        $download = $this->downloadFrom('pages::reports.discipline');

        $this->assertStringContainsString('.xlsx', $download['name']);

        $sheet = $this->sheetXml(base64_decode($download['content']));

        $this->assertStringContainsString('شرح', $sheet);
        $this->assertStringContainsString('تاریخ (شمسی)', $sheet);
        $this->assertStringContainsString('با تأخیر وارد کلاس شد', $sheet);
    }

    /**
     * افکت «download» همان چیزی است که Livewire در مرورگر می‌فرستد؛ تست باید
     * همان را بخواند نه یک مسیر جایگزین، وگرنه دکمهٔ دانلود ممکن است در
     * صفحه بشکند و تست سبز بماند.
     *
     * @return array{name: string, content: string}
     */
    private function downloadFrom(string $component): array
    {
        $effects = Livewire::test($component)->call('download')->effects;

        $download = $effects['download'] ?? null;

        $this->assertIsArray($download, 'اکشن دانلود باید افکت download برگرداند');

        return $download;
    }
}
