namespace Tests\Feature;

use App\Enums\Role;
use App\Models\Invoice;
use App\Models\Payroll;
use App\Models\Setting;
use App\Models\Student;
use App\Models\User;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Tests\TestCase;

/*
|---------------------------------------------------------------------------
| سربرگ چاپ PDF با لوگو و شمارهٔ سند (شماره 60)
|
| هر سند چاپی همان سربرگ را دارد: لوگو (یا نام آموزشگاه وقتی لوگو نیست)،
| نام و نشانی، و در سمت چپ عنوان سند با شمارهٔ سند و تاریخ شمسی. چهار
| سند با این سربرگ چاپ می‌شوند؛ رسیدِ ۸۰ میلی‌متری طرحِ خودش را دارد و
| فقط لوگو را از همین جا می‌گیرد.
*/

class PrintHeaderTest extends TestCase
{
    use RefreshDatabase;

    private function actingAsRole(Role $role): User
    {
        $user = User::factory()->role($role)->create();

        $this->actingAs($user);

        return $user;
    }

    public function test_the_header_shows_the_logo_when_one_is_configured(): void
    {
        $this->actingAsRole(Role::Admin);
        Setting::put(Setting::ACADEMY_LOGO, '/img/logo.png');

        $this->get(route('students.transcript.print', Student::factory()->create()))
            ->assertOk()
            ->assertSee('/img/logo.png', false)
            ->assertSee('لوگوی آموزشگاه', false);
    }

    public function test_the_academy_name_is_the_header_when_there_is_no_logo(): void
    {
        $this->actingAsRole(Role::Admin);
        Setting::put(Setting::ACADEMY_NAME, 'آموزشگاه دانش‌نویس');

        $response = $this->get(route('students.transcript.print', Student::factory()->create()));

        $response->assertOk()->assertSee('آموزشگاه دانش‌نویس');
        // بدون لوگو نباید تگ تصویرِ خالی روی کاغذ بیفتد
        $this->assertStringNotContainsString('<img', $response->getContent());
    }

    public function test_the_transcript_carries_its_document_number_and_jalali_date(): void
    {
        $this->actingAsRole(Role::Admin);

        $this->get(route('students.transcript.print', Student::factory()->create()))
            ->assertOk()
            ->assertSee('شماره سند')
            ->assertSee('تاریخ صدور');
    }

    public function test_the_invoice_uses_the_shared_header(): void
    {
        $this->actingAsRole(Role::Finance);
        $invoice = Invoice::issue(Student::factory()->create(), null, 1_000_000);

        $response = $this->get(route('finance.invoice.print', $invoice));

        $response->assertOk()
            ->assertSee('شماره سند')
            ->assertSee($invoice->number);
    }

    public function test_the_payslip_uses_the_shared_header(): void
    {
        $this->actingAsRole(Role::Admin);
        $payroll = Payroll::factory()->create();

        $this->get(route('payroll.print', $payroll))
            ->assertOk()
            ->assertSee('شماره سند')
            ->assertSee(to_persian_digits((string) $payroll->id));
    }

    public function test_the_receipt_keeps_its_own_layout_but_takes_the_logo(): void
    {
        $this->actingAsRole(Role::Finance);
        Setting::put(Setting::ACADEMY_LOGO, '/img/logo.png');
        $invoice = Invoice::issue(Student::factory()->create(), null, 1_000_000);
        $payment = \App\Models\Payment::pay($invoice, 500_000);

        // رسید روی کارت ۸۰ میلی‌متری می‌رود؛ سربرگ A4 نباید داخلش برود
        $this->get(route('finance.receipt.print', $payment))
            ->assertOk()
            ->assertSee('/img/logo.png', false)
            ->assertSee('80mm');
    }
}
